<?php
namespace App\Services;
use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Storage;
class DatabaseBackupService {
 public function create($createdBy='scheduler'){$filename='ecommerce-'.date('Y-m-d-His').'.sql.gz';$id=DB::table('system_backups')->insertGetId(['filename'=>$filename,'disk'=>'local','status'=>'creating','created_by'=>$createdBy,'created_at'=>now(),'updated_at'=>now()]);$relative='backups/'.$filename;$absolute=storage_path('app/'.$relative);if(!is_dir(dirname($absolute)))mkdir(dirname($absolute),0755,true);try{$out=gzopen($absolute,'wb9');if(!$out)throw new \RuntimeException('Unable to create backup file.');gzwrite($out,"-- Ecommerce database backup\n-- Created: ".date('c')."\nSET FOREIGN_KEY_CHECKS=0;\n\n");$tables=DB::select('SHOW TABLES');foreach($tables as $row){$values=array_values((array)$row);$table=$values[0];$create=DB::select("SHOW CREATE TABLE `".str_replace('`','``',$table)."`");$definition=array_values((array)$create[0])[1];gzwrite($out,"DROP TABLE IF EXISTS `{$table}`;\n{$definition};\n");DB::table($table)->orderBy(DB::raw('1'))->chunk(250,function($rows)use($out,$table){foreach($rows as $row){$columns=array_keys((array)$row);$values=array_map(function($value){return is_null($value)?'NULL':DB::connection()->getPdo()->quote((string)$value);},array_values((array)$row));gzwrite($out,"INSERT INTO `{$table}` (`".implode('`,`',$columns)."`) VALUES (".implode(',',$values).");\n");}});gzwrite($out,"\n");}gzwrite($out,"SET FOREIGN_KEY_CHECKS=1;\n");gzclose($out);$size=filesize($absolute);DB::table('system_backups')->where('id',$id)->update(['status'=>'completed','size_bytes'=>$size,'updated_at'=>now()]);$this->prune(14);return $id;}catch(\Throwable $e){if(isset($out)&&is_resource($out))gzclose($out);if(file_exists($absolute))@unlink($absolute);DB::table('system_backups')->where('id',$id)->update(['status'=>'failed','error'=>substr($e->getMessage(),0,2000),'updated_at'=>now()]);throw $e;}}
 public function prune($days){$old=DB::table('system_backups')->where('created_at','<',now()->subDays($days))->get();foreach($old as $backup){Storage::disk($backup->disk)->delete('backups/'.$backup->filename);DB::table('system_backups')->where('id',$backup->id)->delete();}}
}
